import { Component } from '@angular/core';
import { PieService } from '../../services/pie.service';
import { AsyncPipe, NgFor, NgIf } from '@angular/common';

@Component({
  standalone: true,
  imports: [
    NgFor,
    NgIf,
    AsyncPipe,
  ],
  selector: 'app-side-menu',
  templateUrl: './side-menu.component.html',
  styleUrls: ['./side-menu.component.css']
})
export class SideMenuComponent {
  pies$ = this.pieService.filteredPies$;
  selectedPie$ = this.pieService.selectedPie$;

  constructor(
    private readonly pieService: PieService,
  ) {}

  selectPie(id: string){
    this.pieService.setSelectedPie(id);
  }
}
<div class="side-nav" *ngIf="selectedPie$ | async as selectedPie">
  <button
    *ngFor="let pie of pies$ | async"
    class="image-button"
    (click)="selectPie(pie.id)"
  >
    <img
      [src]="pie.thumb"
      alt="image of person sticking a fork in a piece of pie"
    />
  </button>
</div>
